const now = new Date();
const iso = now.toISOString().slice(0, 10);
const label = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
return [{ json: { reportDate: iso, reportDateLabel: label } }];

function randomItem(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function randomInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }

const firstNames = ['Amina','Youssef','Sara','Karim','Lina','Omar','Nadia','Hassan','Imane','Yassine','Salma','Rachid','Fatima','Adil','Meryem','Anas'];
const lastNames = ['El Amrani','Bouzid','Chraibi','Idrissi','Tazi','Benali','Fassi','Alaoui','Ziani','Bennis'];
const departments = ['Engineering','Sales','Marketing','HR','Finance','Operations','Support','Legal'];
const jobTitles = ['Software Engineer','Sales Representative','Marketing Specialist','HR Coordinator','Financial Analyst','Operations Manager','Support Agent','Legal Counsel'];
const seniorities = ['junior','mid','senior','lead'];
const contractTypes = ['full_time','part_time','contract','intern'];
const statuses = ['active','on_leave','terminated'];

const rows = [];
const count = randomInt(8, 12);
for (let i = 0; i < count; i++) {
  const first = randomItem(firstNames);
  const last = randomItem(lastNames);
  rows.push({
    json: {
      'Full Name': `${first} ${last}`,
      'Email': `${first}.${last}`.toLowerCase().replace(/\s+/g, '') + '@example.com',
      'Department': randomItem(departments),
      'Job Title': randomItem(jobTitles),
      'Seniority': randomItem(seniorities),
      'Contract Type': randomItem(contractTypes),
      'Status': randomItem(statuses),
      'Performance Score': randomInt(50, 100),
    },
  });
}
return rows;

function randomItem(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function randomInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function pad(n) { return String(n).padStart(2, '0'); }

const firstNames = ['Amina','Youssef','Sara','Karim','Lina','Omar','Nadia','Hassan','Imane','Yassine','Salma','Rachid','Fatima','Adil','Meryem','Anas'];
const lastNames = ['El Amrani','Bouzid','Chraibi','Idrissi','Tazi','Benali','Fassi','Alaoui','Ziani','Bennis'];
const departments = ['Engineering','Sales','Marketing','HR','Finance','Operations','Support','Legal'];
const statuses = ['present','late','absent'];
const reportDate = $('Compute Report Date').item.json.reportDate;

const rows = [];
const count = randomInt(8, 12);
for (let i = 0; i < count; i++) {
  const status = randomItem(statuses);
  const checkInHour = randomInt(7, 9);
  const checkInMin = randomInt(0, 59);
  const hoursWorked = status === 'absent' ? 0 : randomInt(6, 9);
  const checkIn = status === 'absent' ? '' : `${pad(checkInHour)}:${pad(checkInMin)}`;
  const checkOut = status === 'absent' ? '' : `${pad(checkInHour + hoursWorked)}:${pad(checkInMin)}`;
  rows.push({
    json: {
      'Full Name': `${randomItem(firstNames)} ${randomItem(lastNames)}`,
      'Department': randomItem(departments),
      'Date': reportDate,
      'Status': status,
      'Check In': checkIn,
      'Check Out': checkOut,
      'Hours Worked': hoursWorked,
    },
  });
}
return rows;
